#!/usr/bin/env python3
"""Materialize the reviewed B0 v2 verified-use kernel on an exact source tree."""

from __future__ import annotations

import base64
import gzip
from pathlib import Path

VERIFIED_USE_GZIP_B64 = ""
VERIFIED_USE_TESTS_GZIP_B64 = ""


def decode(payload: str) -> bytes:
    return gzip.decompress(base64.b64decode(payload, validate=True))


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"expected exactly one {label}, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def main() -> int:
    Path("codex-rs/hepta-contracts/src/verified_use.rs").write_bytes(
        decode(VERIFIED_USE_GZIP_B64)
    )
    Path("codex-rs/hepta-contracts/src/verified_use_tests.rs").write_bytes(
        decode(VERIFIED_USE_TESTS_GZIP_B64)
    )

    old_exports = """pub use verified_use::PhysicalCapabilityKind;
pub use verified_use::PhysicalUseFinalCheck;
pub use verified_use::PhysicalUseVerification;
pub use verified_use::PhysicalUseVerificationRequest;
pub use verified_use::PhysicalUseVerifier;
pub use verified_use::PhysicalUseWindow;
pub use verified_use::RevocationRevision;
pub use verified_use::VERIFIED_USE_SCHEMA_VERSION;
pub use verified_use::VerifiedUseError;
pub use verified_use::VerifiedUseToken;
pub use verified_use::VerifiedUseWitness;
pub use verified_use::verify_physical_capability_use;"""
    new_exports = """pub use verified_use::MAX_VERIFIED_USE_LIFETIME_SECONDS;
pub use verified_use::PhysicalCapabilityKind;
pub use verified_use::PhysicalUseFinalCheck;
pub use verified_use::PhysicalUseLifetime;
pub use verified_use::PhysicalUseVerification;
pub use verified_use::PhysicalUseVerificationPhase;
pub use verified_use::PhysicalUseVerificationRequest;
pub use verified_use::PhysicalUseVerifier;
pub use verified_use::RevocationRevision;
pub use verified_use::VERIFIED_USE_SCHEMA_VERSION;
pub use verified_use::VerifiedUseBoundaryPermit;
pub use verified_use::VerifiedUseClaimKey;
pub use verified_use::VerifiedUseClaimPhase;
pub use verified_use::VerifiedUseClaimReceipt;
pub use verified_use::VerifiedUseClaimRecord;
pub use verified_use::VerifiedUseClaimStore;
pub use verified_use::VerifiedUseError;
pub use verified_use::VerifiedUseToken;
pub use verified_use::VerifiedUseWitness;
pub use verified_use::verify_physical_capability_use;"""
    replace_once(
        Path("codex-rs/hepta-contracts/src/lib.rs"),
        old_exports,
        new_exports,
        "verified-use export block",
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
